    // We aim to minimize post_residual, but penalize "fragmentation" (small remainders that cannot fit typical items)
    // and reward bins that leave space for the next expected item.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty:
    // If post_residual is small but > 0, it's often wasted space. 
    // We heavily penalize post_residual values in the range [1, 9] (too small to fit any item).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Compatibility:
    // If the next item can fit into the remaining space, we favor this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating a new bin. 
    // We only open a new bin if the current open bins are "bad" (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if existing fitting bins are suboptimal (high mean_residual)
            score = mean_residual * 0.8;
        }
    }

    // 4. Fitting Pressure:
    // If this is the only bin that can fit the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Harmonic Balance:
    // Favor residuals that are multiples of 10 or 20, as they align well with common item size distributions.
    let harmonic_penalty = (post_residual % 10) as f64 * 1.5;
    score += harmonic_penalty;

    score
}
